    expect(body.includes(['describe(', "'post239 routes"].join(''))).toBe(false);
    expect(body.includes(['describe(', "'post239 mcp-spec"].join(''))).toBe(false);
    expect(body.includes(['describe(', "'post239 wrangler"].join(''))).toBe(false);
